-- ------------------------------------------------------------
-- Table structure for `audit_logs`
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `audit_logs`;
CREATE TABLE `audit_logs` (
  `id` char(36) NOT NULL,
  `tenant_id` char(36) DEFAULT NULL,
  `actor_user_id` char(36) DEFAULT NULL,
  `actor_name` varchar(255) NOT NULL DEFAULT '',
  `role` enum('super_admin','owner','manager','cashier','waiter','kitchen','barista') DEFAULT NULL,
  `category` enum('auth','tenant','staff','order','payment','inventory','product','settings','subscription','module','system') NOT NULL DEFAULT 'system',
  `action` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `ip` varchar(45) DEFAULT NULL,
  `user_agent` text DEFAULT NULL,
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`metadata`)),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_audit_logs_tenant` (`tenant_id`),
  KEY `idx_audit_logs_created` (`created_at`),
  KEY `idx_audit_logs_category` (`category`),
  KEY `audit_logs_ibfk_2` (`actor_user_id`),
  CONSTRAINT `audit_logs_ibfk_1` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE SET NULL,
  CONSTRAINT `audit_logs_ibfk_2` FOREIGN KEY (`actor_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

