DROP TABLE IF EXISTS `chat_conversations`;
CREATE TABLE `chat_conversations` (
  `id` varchar(36) NOT NULL DEFAULT uuid(),
  `session_id` varchar(36) NOT NULL,
  `visitor_name` varchar(255) DEFAULT NULL,
  `visitor_email` varchar(255) DEFAULT NULL,
  `topic` enum('sales','support','billing','general') DEFAULT 'general',
  `status` enum('active','resolved','pending_review','escalated') DEFAULT 'active',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `assigned_agent_id` varchar(36) DEFAULT NULL,
  `is_bot_handled` tinyint(1) DEFAULT 1,
  `waiting_since` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `priority` enum('low','normal','high','urgent') DEFAULT 'normal',
  PRIMARY KEY (`id`),
  KEY `idx_chat_conv_agent` (`assigned_agent_id`),
  KEY `idx_chat_conv_waiting` (`waiting_since`),
  CONSTRAINT `chat_conversations_ibfk_1` FOREIGN KEY (`assigned_agent_id`) REFERENCES `support_agents` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

