-- ------------------------------------------------------------
-- Table structure for `chat_messages`
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `chat_messages`;
CREATE TABLE `chat_messages` (
  `id` varchar(36) NOT NULL DEFAULT uuid(),
  `conversation_id` varchar(36) NOT NULL,
  `sender_type` enum('user','bot','admin') NOT NULL,
  `message` text NOT NULL,
  `knowledge_id` varchar(36) DEFAULT NULL,
  `is_answered` tinyint(1) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `agent_id` varchar(36) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `knowledge_id` (`knowledge_id`),
  KEY `idx_chat_msg_conv` (`conversation_id`),
  KEY `agent_id` (`agent_id`),
  CONSTRAINT `chat_messages_ibfk_1` FOREIGN KEY (`conversation_id`) REFERENCES `chat_conversations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chat_messages_ibfk_2` FOREIGN KEY (`knowledge_id`) REFERENCES `chat_knowledge_base` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chat_messages_ibfk_3` FOREIGN KEY (`agent_id`) REFERENCES `support_agents` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Data for `chat_messages`
INSERT INTO `chat_messages` (`id`, `conversation_id`, `sender_type`, `message`, `knowledge_id`, `is_answered`, `created_at`, `agent_id`) VALUES
('0630759b-b6a3-47f7-9984-ffa7394a92cc', 'e9319c95-3f72-4fd2-bba8-b3ffed431708', 'bot', 'I appreciate your question! This requires assistance from our support team.

⏳ **Current Status:** All our support agents are currently helping other customers.

📝 **What happens next:**
• Your message has been added to our queue
• A support agent will respond as soon as available
• You''ll receive a notification when they reply

💡 **While you wait:**
• You can continue browsing our website
• Check our FAQ for quick answers
