-- ------------------------------------------------------------
-- Table structure for `invoices`
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `invoices`;
CREATE TABLE `invoices` (
  `id` char(36) NOT NULL,
  `tenant_id` char(36) NOT NULL,
  `number` varchar(50) NOT NULL,
  `amount` decimal(15,2) NOT NULL,
  `plan` enum('free','basic','premium','enterprise') NOT NULL,
  `status` enum('draft','issued','paid','overdue','void') NOT NULL DEFAULT 'issued',
  `issued_at` date NOT NULL,
  `due_at` date NOT NULL,
  `paid_at` date DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `number` (`number`),
  KEY `idx_invoices_tenant` (`tenant_id`),
  CONSTRAINT `invoices_ibfk_1` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

