-- ------------------------------------------------------------
-- Table structure for `platform_settings`
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `platform_settings`;
CREATE TABLE `platform_settings` (
  `id` int(11) NOT NULL DEFAULT 1,
  `company_name` varchar(100) DEFAULT 'ProManage',
  `company_tagline` varchar(200) DEFAULT 'Complete Restaurant Management Solution',
  `company_description` text DEFAULT NULL,
  `hero_title` varchar(255) DEFAULT 'The complete command center for your restaurant',
  `hero_subtitle` text DEFAULT 'From orders to inventory, staffing to analytics — manage every aspect of your restaurant with our powerful, intuitive ERP system designed specifically for the food service industry.',
  `hero_cta_text` varchar(50) DEFAULT 'Get Started',
  `hero_secondary_cta_text` varchar(50) DEFAULT 'Contact Sales',
  `contact_phone` varchar(50) DEFAULT '+251 954 668 305',
  `contact_email` varchar(100) DEFAULT 'support@promanage.com',
  `contact_address` text DEFAULT NULL,
  `contact_city` varchar(100) DEFAULT 'Addis Ababa',
  `contact_country` varchar(100) DEFAULT 'Ethiopia',
  `social_facebook` varchar(255) DEFAULT NULL,
  `social_twitter` varchar(255) DEFAULT NULL,
  `social_linkedin` varchar(255) DEFAULT NULL,
  `social_instagram` varchar(255) DEFAULT NULL,
  `social_youtube` varchar(255) DEFAULT NULL,
  `footer_text` text DEFAULT '© 2024 ProManage. All rights reserved.',
  `footer_links` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`footer_links`)),
  `seo_title` varchar(255) DEFAULT 'ProManage - Restaurant Management System',
  `seo_description` text DEFAULT 'Complete restaurant management solution with POS, inventory, staff management, and analytics.',
  `seo_keywords` text DEFAULT NULL,
  `features_title` varchar(255) DEFAULT 'Everything you need to run your restaurant',
  `features_subtitle` text DEFAULT 'Powerful features designed specifically for the food service industry',
  `features` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`features`)),
  `benefits_title` varchar(255) DEFAULT 'Why choose ProManage?',
  `benefits` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`benefits`)),
  `testimonials_enabled` tinyint(1) DEFAULT 0,
  `testimonials` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`testimonials`)),
  `maintenance_mode` tinyint(1) DEFAULT 0,
  `maintenance_message` text DEFAULT NULL,
  `maintenance_title` varchar(255) DEFAULT NULL,
  `maintenance_estimated_return` datetime DEFAULT NULL,
  `maintenance_contact_email` varchar(255) DEFAULT NULL,
  `maintenance_contact_phone` varchar(80) DEFAULT NULL,
  `maintenance_logo_url` text DEFAULT NULL,
  `maintenance_bg_url` text DEFAULT NULL,
  `maintenance_allow_admins` tinyint(1) NOT NULL DEFAULT 0,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `updated_by` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

