-- ------------------------------------------------------------
-- Table structure for `rms_inventory`
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `rms_inventory`;
CREATE TABLE `rms_inventory` (
  `id` char(36) NOT NULL,
  `tenant_id` char(36) DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  `stock` decimal(15,2) NOT NULL DEFAULT 0.00,
  `unit` varchar(50) NOT NULL DEFAULT 'pcs',
  `threshold` decimal(15,2) NOT NULL DEFAULT 0.00,
  `maximum_stock_capacity` decimal(15,2) DEFAULT NULL,
  `low_stock_percent` decimal(5,2) NOT NULL DEFAULT 20.00,
  `unit_price` decimal(15,2) NOT NULL DEFAULT 0.00,
  `purchase_date` varchar(50) DEFAULT NULL,
  `adjustment_date` varchar(50) DEFAULT NULL,
  `expiry_date` varchar(50) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_tenant_inventory_name` (`tenant_id`,`name`),
  KEY `idx_rms_inventory_tenant` (`tenant_id`),
  CONSTRAINT `rms_inventory_ibfk_1` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

