-- ------------------------------------------------------------
-- Table structure for `rms_notifications`
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `rms_notifications`;
CREATE TABLE `rms_notifications` (
  `id` varchar(100) NOT NULL,
  `tenant_id` char(36) DEFAULT NULL,
  `message` text NOT NULL,
  `kind` varchar(50) NOT NULL,
  `ts` bigint(20) NOT NULL,
  `read` tinyint(1) NOT NULL DEFAULT 0,
  `target_roles` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`target_roles`)),
  PRIMARY KEY (`id`),
  KEY `idx_rms_notifications_tenant` (`tenant_id`),
  CONSTRAINT `rms_notifications_ibfk_1` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------
-- Table structure for `rms_orders`
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `rms_orders`;
CREATE TABLE `rms_orders` (
  `id` varchar(100) NOT NULL,
  `tenant_id` char(36) DEFAULT NULL,
  `table_name` varchar(100) NOT NULL,
  `product_id` varchar(100) NOT NULL,
  `product` varchar(255) NOT NULL,
  `station` varchar(100) NOT NULL,
  `waiter` varchar(255) NOT NULL,
  `status` varchar(50) NOT NULL,
  `total` decimal(15,2) NOT NULL DEFAULT 0.00,
  `billed` tinyint(1) NOT NULL DEFAULT 0,
  `note` text DEFAULT NULL,
  `created_at_ms` bigint(20) NOT NULL,
  `item_count` int(11) DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_rms_orders_table_billed` (`table_name`,`billed`),
  KEY `idx_rms_orders_tenant` (`tenant_id`),
  CONSTRAINT `rms_orders_ibfk_1` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

