-- ------------------------------------------------------------
-- Table structure for `rms_products`
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `rms_products`;
CREATE TABLE `rms_products` (
  `id` varchar(100) NOT NULL,
  `tenant_id` char(36) DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  `category` varchar(100) NOT NULL DEFAULT '',
  `sub` varchar(100) NOT NULL DEFAULT '',
  `price` decimal(15,2) NOT NULL DEFAULT 0.00,
  `stock` decimal(15,2) NOT NULL DEFAULT 0.00,
  `unit` varchar(50) NOT NULL DEFAULT 'pcs',
  `station` varchar(100) NOT NULL DEFAULT 'Kitchen',
  `image` text DEFAULT NULL,
  `ingredients` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`ingredients`)),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `visible` tinyint(1) DEFAULT 1 COMMENT 'Product visibility: 1=visible, 0=hidden',
  PRIMARY KEY (`id`),
  KEY `idx_rms_products_tenant` (`tenant_id`),
  CONSTRAINT `rms_products_ibfk_1` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

