-- ------------------------------------------------------------
-- Table structure for `rms_recipes`
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `rms_recipes`;
CREATE TABLE `rms_recipes` (
  `product_id` varchar(100) NOT NULL,
  `tenant_id` char(36) NOT NULL,
  `lines` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`lines`)),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`tenant_id`,`product_id`),
  KEY `idx_rms_recipes_tenant` (`tenant_id`),
  CONSTRAINT `rms_recipes_ibfk_1` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

