-- Table structure for `subscription_notifications`
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `subscription_notifications`;
CREATE TABLE `subscription_notifications` (
  `id` char(36) NOT NULL,
  `tenant_id` char(36) NOT NULL,
  `notification_type` enum('expiry_30_days','expiry_14_days','expiry_7_days','expiry_3_days','expiry_1_day','expired','payment_received','payment_verified','payment_rejected') NOT NULL,
  `sent_at` timestamp NOT NULL DEFAULT current_timestamp(),
