  PRIMARY KEY (`id`),
  KEY `idx_notifications_tenant` (`tenant_id`),
  CONSTRAINT `sub_notifications_ibfk_1` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

