-- ------------------------------------------------------------
-- Table structure for `support_agents`
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `support_agents`;
CREATE TABLE `support_agents` (
  `id` varchar(36) NOT NULL DEFAULT uuid(),
  `email` varchar(255) NOT NULL,
  `password_hash` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `avatar` longtext DEFAULT NULL,
  `role` enum('agent','supervisor') DEFAULT 'agent',
  `status` enum('online','away','offline') DEFAULT 'offline',
  `max_concurrent_chats` int(11) DEFAULT 5,
  `current_chats` int(11) DEFAULT 0,
  `specialization` enum('sales','support','billing','general') DEFAULT 'general',
  `active` tinyint(1) DEFAULT 1,
  `last_seen` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `rating` decimal(2,1) DEFAULT 0.0,
  `rating_count` int(11) DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`),
  KEY `idx_support_agents_status` (`status`),
  KEY `idx_support_agents_active` (`active`),
  KEY `idx_support_agents_spec` (`specialization`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

