CREATE TABLE `tenants` (
  `id` char(36) NOT NULL,
  `name` varchar(255) NOT NULL,
  `type` varchar(100) NOT NULL DEFAULT 'Restaurant',
  `plan` enum('free','basic','premium','enterprise') NOT NULL DEFAULT 'basic',
  `color` varchar(20) NOT NULL DEFAULT '#5b8def',
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `expires_at` date NOT NULL,
  `grace_days` int(11) NOT NULL DEFAULT 7,
  `revenue` decimal(15,2) NOT NULL DEFAULT 0.00,
  `currency` varchar(10) NOT NULL DEFAULT 'USD',
  `calendar_type` enum('gregorian','ethiopian') NOT NULL DEFAULT 'gregorian',
  `disabled_modules` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`disabled_modules`)),
  `settings` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`settings`)),
  `legacy_id` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `suspension_reason` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `legacy_id` (`legacy_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

